/*
 * test_pcode.c -- the flight algorithms against their pseudocode (the .pc files of fsw/pseudocode,
 * docs/PSEUDOCODE_V2.md): every vector the interpreter drew (pcode_vectors.h, generated by
 * tools/pcode.py gen) through the hand-written C. A function with no transcendental must agree
 * bit for bit; one with, to 1e-12 relative. A proc's vectors are a run of calls, its state carried.
 * Owner: Agastya. Copyright (c) 2026 Agastya. All rights reserved.
 */
#include <stdio.h>
#include <string.h>
#include <math.h>
#include "adcs_gnc.h"
#include "adcs_math.h"
#include "adcs_fsw_int.h"
#include "pcode_vectors.h"

/* functions of the pseudocode the C flight software has no function for, and why */
static const char *const NOT_IN_C[][2] = {
    {"control::mtq_err", "static in adcs_ctl.c; checked through the four laws that call it (Lovera, Celani, Avanzini, TANGO)"},
    {"estimation::update3", "static in adcs_est.c; checked through mekf_vector and mekf_quat, which call it"},
    {NULL, NULL},
};

typedef struct { const double *x; int at; } in_t;
static double F(in_t *a) { return a->x[a->at++]; }
static void V(in_t *a, double *v, int n) { int i; for (i = 0; i < n; i++) v[i] = F(a); }
static void M3(in_t *a, double m[3][3]) { int i; for (i = 0; i < 3; i++) V(a, m[i], 3); }

typedef struct { double y[512]; int n; } out_t;
static void O(out_t *o, double v) { o->y[o->n++] = v; }
static void OV(out_t *o, const double *v, int n) { int i; for (i = 0; i < n; i++) O(o, v[i]); }
static void OM3(out_t *o, double m[3][3]) { int i; for (i = 0; i < 3; i++) OV(o, m[i], 3); }

/* one call of a pseudocode function through the C flight software: 1, or 0 when not adapted */
static int call(const char *name, const double *x, int nx, out_t *o)
{
    in_t a = {x, 0};
    o->n = 0;
    if (!strcmp(name, "math::maxabs3")) { double v[3]; V(&a, v, 3); O(o, adcs_maxabs3(v)); }
    else if (!strcmp(name, "math::mat3t_vec")) { double m[3][3], v[3], r[3]; M3(&a, m); V(&a, v, 3); adcs_mat3t_vec(m, v, r); OV(o, r, 3); }
    else if (!strcmp(name, "math::skew")) { double v[3], m[3][3]; V(&a, v, 3); adcs_skew(v, m); OM3(o, m); }
    else if (!strcmp(name, "math::det3")) { double m[3][3]; M3(&a, m); O(o, adcs_det3(m)); }
    else if (!strcmp(name, "math::inv3")) { double m[3][3], r[3][3]; int ok; M3(&a, m); ok = adcs_inv3(m, r) == 0; OM3(o, r); O(o, ok); }
    else if (!strcmp(name, "math::pinv_rows")) {
        double A[3][8], P[8][3]; int i, n;
        for (i = 0; i < 3; i++) V(&a, A[i], 8);
        n = (int)F(&a);
        memset(P, 0, sizeof P);
        adcs_pinv_rows(A, n, P);
        for (i = 0; i < 8; i++) OV(o, P[i], 3);
    }
    else if (!strcmp(name, "math::jacobi_eig4")) {
        double K[4][4], l[4], W[4][4]; int i;
        for (i = 0; i < 4; i++) V(&a, K[i], 4);
        adcs_jacobi_eig4(K, l, W); OV(o, l, 4);
        for (i = 0; i < 4; i++) OV(o, W[i], 4);
    }
    else if (!strcmp(name, "math::qmult")) { double p[4], q[4], r[4]; V(&a, p, 4); V(&a, q, 4); adcs_qmult(p, q, r); OV(o, r, 4); }
    else if (!strcmp(name, "math::qconj")) { double q[4], r[4]; V(&a, q, 4); adcs_qconj(q, r); OV(o, r, 4); }
    else if (!strcmp(name, "math::qnorm")) { double q[4]; V(&a, q, 4); adcs_qnorm(q); OV(o, q, 4); }
    else if (!strcmp(name, "math::dcm")) { double q[4], m[3][3]; V(&a, q, 4); adcs_dcm(q, m); OM3(o, m); }
    else if (!strcmp(name, "math::fromdcm")) { double m[3][3], q[4]; M3(&a, m); adcs_fromdcm(m, q); OV(o, q, 4); }
    else if (!strcmp(name, "math::fromrotvec")) { double v[3], q[4]; V(&a, v, 3); adcs_fromrotvec(v, q); OV(o, q, 4); }
    else if (!strcmp(name, "math::qangle")) { double p[4], q[4]; V(&a, p, 4); V(&a, q, 4); O(o, adcs_qangle(p, q)); }
    else if (!strcmp(name, "math::qerr")) { double p[4], q[4], r[4]; V(&a, p, 4); V(&a, q, 4); adcs_qerr(p, q, r); OV(o, r, 4); }
    else if (!strcmp(name, "guidance::guid_kind")) { O(o, adcs_guid_kind((uint8_t)F(&a))); }
    else if (!strcmp(name, "guidance::guidance")) {
        adcs_guid_t g; double r[3], v[3], t, q[4], w[3], wd[3]; int kind;
        memset(&g, 0, sizeof g);
        kind = (int)F(&a); V(&a, r, 3); V(&a, v, 3); t = F(&a);
        V(&a, g.q_off, 4); g.roll_deg = F(&a); g.t0 = F(&a); g.T = F(&a); V(&a, g.axis, 3); V(&a, g.q_inertial, 4);
        V(&a, g.sun_axis, 3); V(&a, g.roll_axis, 3); V(&a, g.sun_eci, 3); g.flip = F(&a) != 0;
        adcs_guidance(kind, r, v, t, &g, q, w, wd);
        OV(o, q, 4); OV(o, w, 3); OV(o, wd, 3);
    }
    else if (!strcmp(name, "guidance::yaw_flip")) {
        adcs_guid_t g; double r[3], v[3], h;
        memset(&g, 0, sizeof g);
        V(&a, r, 3); V(&a, v, 3); V(&a, g.q_off, 4); V(&a, g.sun_axis, 3); V(&a, g.roll_axis, 3); V(&a, g.sun_eci, 3);
        g.flip = F(&a) != 0; h = F(&a);
        adcs_yaw_flip(&g, r, v, h);
        O(o, g.flip ? 1 : 0);
    }
    else if (!strcmp(name, "estimation::mekf_init")) {
        adcs_mekf_t k; double q[4], sa, sb; int i;
        V(&a, q, 4); sa = F(&a); sb = F(&a);
        adcs_mekf_init(&k, q, sa, sb, 0, 0);
        OV(o, k.q, 4); OV(o, k.b, 3); for (i = 0; i < 6; i++) OV(o, k.P[i], 6);
    }
    else if (!strcmp(name, "estimation::mekf_predict")) {
        adcs_mekf_t k; double wm[3], dt; int i;
        V(&a, k.q, 4); V(&a, k.b, 3); for (i = 0; i < 6; i++) V(&a, k.P[i], 6); k.arw = F(&a); k.rrw = F(&a);
        V(&a, wm, 3); dt = F(&a);
        adcs_mekf_predict(&k, wm, dt);
        OV(o, k.q, 4); for (i = 0; i < 6; i++) OV(o, k.P[i], 6);
    }
    else if (!strcmp(name, "estimation::mekf_vector") || !strcmp(name, "estimation::mekf_quat")) {
        adcs_mekf_t k; int i, took;
        V(&a, k.q, 4); V(&a, k.b, 3); for (i = 0; i < 6; i++) V(&a, k.P[i], 6); k.arw = 0; k.rrw = 0;
        if (!strcmp(name, "estimation::mekf_vector")) {
            double bm[3], rr[3], sg, gate;
            V(&a, bm, 3); V(&a, rr, 3); sg = F(&a); gate = F(&a);
            took = adcs_mekf_vector(&k, bm, rr, sg, gate);
        } else {
            double qm[4], sc, sr, bs[3], gate;
            V(&a, qm, 4); sc = F(&a); sr = F(&a); V(&a, bs, 3); gate = F(&a);
            took = adcs_mekf_quat(&k, qm, sc, sr, bs, gate);
        }
        OV(o, k.q, 4); OV(o, k.b, 3); for (i = 0; i < 6; i++) OV(o, k.P[i], 6); O(o, took ? 1 : 0);
    }
    else if (!strcmp(name, "estimation::triad")) {
        double b1[3], b2[3], r1[3], r2[3], q[4] = {0, 0, 0, 0}; int ok;
        V(&a, b1, 3); V(&a, b2, 3); V(&a, r1, 3); V(&a, r2, 3);
        ok = adcs_triad(b1, b2, r1, r2, q) == 0;
        if (!ok) { q[0] = 0; q[1] = 0; q[2] = 0; q[3] = 0; }
        OV(o, q, 4); O(o, ok);
    }
    else if (!strcmp(name, "estimation::quest")) {
        double b[16][3], r[16][3], w[16], q[4], loss; int i, n;
        for (i = 0; i < 16; i++) V(&a, b[i], 3);
        for (i = 0; i < 16; i++) V(&a, r[i], 3);
        V(&a, w, 16); n = (int)F(&a);
        loss = adcs_quest(b, r, w, n, q);
        OV(o, q, 4); O(o, loss);
    }
    else if (!strcmp(name, "control::control_law")) {
        double q[4], w[3], qr[4], wr[3], iq[3], dt, J[3][3], hs[3], wd[3], tau[3]; adcs_gains_t g;
        memset(&g, 0, sizeof g);
        V(&a, q, 4); V(&a, w, 3); V(&a, qr, 4); V(&a, wr, 3); V(&a, iq, 3); dt = F(&a);
        g.law = (int)F(&a); V(&a, g.Kp, 3); V(&a, g.Kd, 3); V(&a, g.Ki, 3); M3(&a, g.Klqr); g.lambda = F(&a); g.phi = F(&a);
        V(&a, g.Gs, 3); g.err_max = F(&a); g.int_max = F(&a);
        M3(&a, J); V(&a, hs, 3); V(&a, wd, 3);
        adcs_control_law(q, w, qr, wr, iq, dt, &g, J, hs, wd, tau);
        OV(o, tau, 3); OV(o, iq, 3);
    }
    else if (!strcmp(name, "control::mtq_pd")) {
        double q[4], w[3], qr[4], wr[3], tau[3]; adcs_gains_t g;
        memset(&g, 0, sizeof g);
        V(&a, q, 4); V(&a, w, 3); V(&a, qr, 4); V(&a, wr, 3); V(&a, g.Kp, 3); V(&a, g.Kd, 3);
        adcs_mtq_pd(q, w, qr, wr, &g, tau); OV(o, tau, 3);
    }
    else if (!strcmp(name, "control::sat_dipole")) { double m[3]; V(&a, m, 3); adcs_sat_dipole(m, F(&a)); OV(o, m, 3); }
    else if (!strcmp(name, "control::torque2dipole")) { double t[3], b[3], m[3], mm; V(&a, t, 3); V(&a, b, 3); mm = F(&a); adcs_torque2dipole(t, b, mm, m); OV(o, m, 3); }
    else if (!strcmp(name, "control::bdot")) {
        double b1[3], b2[3], dt, bn, k, mm, m[3];
        V(&a, b1, 3); V(&a, b2, 3); dt = F(&a); bn = F(&a); k = F(&a); mm = F(&a);
        adcs_bdot(b1, b2, dt, bn, k, mm, m); OV(o, m, 3);
    }
    else if (!strcmp(name, "control::gen_bdot")) { double b[3], bd[3], wd[3], k, m[3]; V(&a, b, 3); V(&a, bd, 3); V(&a, wd, 3); k = F(&a); adcs_gen_bdot(b, bd, wd, k, m); OV(o, m, 3); }
    else if (!strcmp(name, "control::sun_spin") || !strcmp(name, "control::sun_spin_deruiter")) {
        double b[3], w[3], sv[3], J[3][3], m[3], sp, p1, p2, p3; int ecl;
        V(&a, b, 3); V(&a, w, 3); V(&a, sv, 3); ecl = F(&a) != 0; M3(&a, J); sp = F(&a); p1 = F(&a); p2 = F(&a); p3 = F(&a);
        if (!strcmp(name, "control::sun_spin")) adcs_sun_spin(b, w, sv, ecl, J, sp, p1, p2, p3, m);
        else adcs_sun_spin_deruiter(b, w, sv, ecl, J, sp, p1, p2, p3, m);
        OV(o, m, 3);
    }
    else if (!strcmp(name, "control::mtq_lovera")) {
        double q[4], w[3], qr[4], wr[3], J[3][3], e, kp, kv, tau[3];
        V(&a, q, 4); V(&a, w, 3); V(&a, qr, 4); V(&a, wr, 3); M3(&a, J); e = F(&a); kp = F(&a); kv = F(&a);
        adcs_mtq_lovera(q, w, qr, wr, J, e, kp, kv, tau); OV(o, tau, 3);
    }
    else if (!strcmp(name, "control::mtq_celani")) {
        double q[4], w[3], qr[4], wr[3], e, k1, k2, tau[3];
        V(&a, q, 4); V(&a, w, 3); V(&a, qr, 4); V(&a, wr, 3); e = F(&a); k1 = F(&a); k2 = F(&a);
        adcs_mtq_celani(q, w, qr, wr, e, k1, k2, tau); OV(o, tau, 3);
    }
    else if (!strcmp(name, "control::mtq_avanzini")) {
        double q[4], w[3], qr[4], wr[3], J[3][3], k, lam, tau[3] = {0, 0, 0}; int ok;
        V(&a, q, 4); V(&a, w, 3); V(&a, qr, 4); V(&a, wr, 3); M3(&a, J); k = F(&a); lam = F(&a);
        ok = adcs_mtq_avanzini(q, w, qr, wr, J, k, lam, tau);
        if (!ok) { tau[0] = 0; tau[1] = 0; tau[2] = 0; }
        OV(o, tau, 3); O(o, ok);
    }
    else if (!strcmp(name, "control::mtq_boresight")) {
        double e3[3], t[3], we[3], kp, kd, tau[3];
        V(&a, e3, 3); V(&a, t, 3); V(&a, we, 3); kp = F(&a); kd = F(&a);
        adcs_mtq_boresight(e3, t, we, kp, kd, tau); OV(o, tau, 3);
    }
    else if (!strcmp(name, "control::mtq_tango")) {
        double q[4], w[3], qr[4], wr[3], Pth[3][3], Pw[3][3], tau[3];
        V(&a, q, 4); V(&a, w, 3); V(&a, qr, 4); V(&a, wr, 3); M3(&a, Pth); M3(&a, Pw);
        adcs_mtq_tango(q, w, qr, wr, Pth, Pw, tau); OV(o, tau, 3);
    }
    else if (!strcmp(name, "allocation::rotor_axes")) {
        static adcs_params_t p; double d[4], A[3][8]; int i;
        memset(&p, 0, sizeof p); memset(A, 0, sizeof A);
        p.nr = (uint8_t)F(&a); for (i = 0; i < 8; i++) V(&a, p.rot_a0[i], 3);
        for (i = 0; i < 8; i++) p.rot_gi[i] = (uint8_t)F(&a);
        for (i = 0; i < 4; i++) V(&a, p.gim_axis[i], 3);
        V(&a, d, 4);
        adcs_rotor_axes(&p, d, A);
        for (i = 0; i < 3; i++) OV(o, A[i], 8);
    }
    else if (!strcmp(name, "allocation::steer_sr")) {
        static adcs_params_t p; double tau[3], A[3][8], h[8], g[4] = {0, 0, 0, 0}, hd[8]; int i, wheels;
        memset(&p, 0, sizeof p); memset(hd, 0, sizeof hd);
        V(&a, tau, 3); for (i = 0; i < 3; i++) V(&a, A[i], 8); V(&a, h, 8);
        p.nr = (uint8_t)F(&a); p.ng = (uint8_t)F(&a); for (i = 0; i < 8; i++) p.rot_gi[i] = (uint8_t)F(&a);
        for (i = 0; i < 4; i++) V(&a, p.gim_axis[i], 3);
        p.gim_rate_max = F(&a); p.cmg_lam0 = F(&a); p.cmg_mu = F(&a); wheels = F(&a) != 0;
        adcs_steer_sr(tau, A, h, &p, wheels, g, hd);
        OV(o, g, 4); OV(o, hd, 8);
    }
    else if (!strcmp(name, "allocation::dump")) {
        double hd[3], ht[3], b[3], k, mm, m[3];
        V(&a, hd, 3); V(&a, ht, 3); V(&a, b, 3); k = F(&a); mm = F(&a);
        adcs_dump(hd, ht, b, k, mm, m); OV(o, m, 3);
    }
    else if (!strcmp(name, "allocation::rcs_duty")) {
        static adcs_params_t p; double req[3], T, duty[6], tau[3]; int i;
        memset(&p, 0, sizeof p);
        V(&a, req, 3); p.nc = (uint8_t)F(&a); for (i = 0; i < 6; i++) V(&a, p.rcs_tau[i], 3); p.rcs_mib = F(&a); p.rcs_res = F(&a); T = F(&a);
        adcs_rcs_duty(req, &p, T, duty, tau);
        OV(o, duty, 6); OV(o, tau, 3);
    }
    else if (!strcmp(name, "estimation::latency")) { double q[4], w[3], l, r[4]; V(&a, q, 4); V(&a, w, 3); l = F(&a); adcs_latency(q, w, l, r); OV(o, r, 4); }
    else if (!strcmp(name, "guidance::boresight_offset")) { double v[3], q[4]; V(&a, v, 3); adcs_boresight_offset(v, q); OV(o, q, 4); }
    else return 0;
    if (a.at != nx) { printf("FAIL %s: the adapter read %d of %d inputs\n", name, a.at, nx); return -1; }
    return 1;
}

static int exempt(const char *name)
{
    int i;
    for (i = 0; NOT_IN_C[i][0]; i++) if (!strcmp(NOT_IN_C[i][0], name)) return 1;
    return 0;
}

int main(void)
{
    int i, j, fails = 0, values = 0, exact = 0, fns = 0;
    double worst = 0;
    out_t o;
    for (i = 0; i < PC_NVECTORS; i++) {
        const pc_vec *v = &PC_VECTORS[i];
        int r;
        if (i == 0 || strcmp(v->name, PC_VECTORS[i - 1].name)) fns++;
        if (exempt(v->name)) continue;
        r = call(v->name, v->x, v->nx, &o);
        if (r == 0) { printf("FAIL %s: no C adapter and no stated reason\n", v->name); fails++; continue; }
        if (r < 0 || o.n != v->ny) { if (r > 0) printf("FAIL %s: %d outputs, the pseudocode %d\n", v->name, o.n, v->ny); fails++; continue; }
        for (j = 0; j < v->ny; j++) {
            double g = o.y[j], w = v->y[j], err = fabs(g - w)/(fabs(w) > 1e-300 ? fabs(w) : 1e-300);
            int same = memcmp(&g, &w, sizeof g) == 0 || (g == 0 && w == 0);
            values++;
            if (same) exact++; else if (err > worst) worst = err;
            if (!same && (v->exact || !(err < 1e-12))) {
                printf("FAIL %s output %d: C %.17g, pseudocode %.17g%s\n", v->name, j, g, w, v->exact ? " (no transcendental: must agree bit for bit)" : "");
                fails++;
            }
        }
    }
    printf("pcode: %d functions, %d values, %d bit for bit, worst relative difference %.1e; %d failure(s)\n", fns, values, exact, worst, fails);
    return fails ? 1 : 0;
}
